#!/usr/bin/env python3
"""
Replies on data permissions (culprits), 3 November 2026. No earlier round needed.

Adds the row groundwater_crops (Dalin et al. 2017, by the author's permission) and
rewords the SkyTruth rows' notes now that SkyTruth has said how to read its service.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

HEAD = "## Replies on data permissions (3 November)"
DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("roundreplies: run from the culprits repository root")
    if HEAD in (root / "HANDOFF.md").read_text(encoding="utf-8"):
        print("roundreplies: already applied")
        return
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    r = git("apply", "--3way", "--binary", path, check=False)
    if r.returncode:
        sys.exit("roundreplies: did not apply: " + r.stderr[-800:])
    git("reset", "-q", check=False)
    print("roundreplies: applied")


if __name__ == "__main__":
    main()
